ALTER TABLE "tenants" ADD CONSTRAINT "tenants_subdomain_check" CHECK ("tenants"."subdomain" ~ '^(?!..--)[a-z0-9][a-z0-9-]{1,30}[a-z0-9]$' and "tenants"."subdomain" not in ('about', 'account', 'admin', 'administrator', 'api', 'app', 'assets', 'auth', 'autoconfig', 'autodiscover', 'billing', 'blog', 'cdn', 'dashboard', 'demo', 'dev', 'docs', 'email', 'fancyfolio', 'ftp', 'help', 'imap', 'localhost', 'login', 'logout', 'mail', 'mta-sts', 'ns1', 'ns2', 'pop', 'pop3', 'preview', 'root', 'security', 'signin', 'signup', 'smtp', 'staging', 'static', 'status', 'support', 'test', 'webmail', 'wpad', 'www'));